<?php declare(strict_types=1);
use FMonitor2\YiiRuntime\Assets\InstallerDirectoryAssetBundle;use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;
InstallerDirectoryAssetBundle::register($this);$date=static fn(?string$v,string$unknown='Неизвестно')=>$v===null?$unknown:($v==='now'?'Сейчас':(new DateTimeImmutable($v))->format('d.m.Y'));$load=['free'=>'Свободен','assigned'=>'1 активное закрепление','unknown'=>'Нет достоверных данных'];ViewSupport::begin($this,(string)$installer['fio'],$identity,'installers');
?><main class="installer-card" data-installer-tab-id="<?=(int)$installer['installer_tab_id']?>">
<div class="fm2-page-header"><div><h1><?=Html::encode($installer['fio'])?></h1><p>таб. <?=str_pad((string)$installer['installer_tab_id'],6,'0',STR_PAD_LEFT)?> · <?=Html::encode($installer['position'])?></p></div><a class="shlz-button shlz-button--secondary" href="<?=Html::encode($returnUrl)?>">К списку монтажников</a></div>
<section class="shlz-panel fm2-installer-profile"><dl><div><dt>Кадровый статус</dt><dd><span class="shlz-status <?=$installer['employment_status']==='employed'?'shlz-status--bright-green':'shlz-status--neutral'?>"><?=$installer['employment_status']==='employed'?'Трудоустроен':'Уволен'?></span></dd></div><div><dt>Активные закрепления</dt><dd><span class="fm2-utilization-status fm2-utilization-status--<?=$installer['load']?>"><?=$installer['load']==='overloaded'?count($installer['assignments']).' активных закреплений':($load[$installer['load']]??'Нет данных')?></span></dd></div><div><dt>Позднейшее плановое окончание</dt><dd><?=$date($installer['planned_release'])?></dd></div></dl></section>
<section class="shlz-panel fm2-list-surface fm2-installer-card-section"><h2>Текущая работа</h2><p data-current-work-count="<?=count($installer['assignments'])?>"><?=count($installer['assignments'])===0?'Нет текущих работ':count($installer['assignments']).' текущие работы'?></p><?php foreach($installer['assignments']as$a):?><p><a class="shlz-link" href="/pilot/objects/<?=(int)$a['object_id']?>"><?=Html::encode($a['registration_number'])?></a> · <?=Html::encode($a['address'])?></p><?php endforeach?></section>
<section class="shlz-panel fm2-list-surface fm2-installer-card-section"><?php if($installer['upcomingAssignments']===[]):?><h2>Будущая загрузка</h2><p>Нет будущих назначений</p><?php else:?><h2>Предстоящее назначение</h2><?php foreach($installer['upcomingAssignments']as$a):?><p><a class="shlz-link" href="/pilot/objects/<?=(int)$a['object_id']?>"><?=Html::encode($a['registration_number'])?></a> · <?=Html::encode($a['address'])?> · <?=$a['planned_start']===null?'Дата начала неизвестна':$date($a['planned_start'])?></p><?php endforeach;endif?></section>
<section class="shlz-panel fm2-list-surface fm2-installer-card-section"><h2>История участия</h2><?php if($periods===[]):?><p>История закреплений отсутствует</p><?php else:?><ol data-utilization-timeline><?php foreach($periods as$p):?><li data-history-period data-object-id="<?=$p['object_id']?>" data-start="<?=Html::encode($p['start'])?>"><a class="shlz-link" href="/pilot/objects/<?=$p['object_id']?>"><?=Html::encode($p['registration_number'])?></a> · <?=$date($p['start'])?> — <?=$p['end']===null?'продолжается':$date($p['end'])?></li><?php endforeach?></ol><?php endif?><?=ViewSupport::pagination('/pilot/installers/'.$installer['installer_tab_id'],$history['page'],$history['pages'],$history['total'],50,[],'Страницы истории закреплений')?></section></main><?php ViewSupport::end($this);
